macro_rules! deps {
    () => {
        ForceCaptureTraitArgs!();
    };
}

macro_rules! variance_of_opaque {
    () => {
        deps!();
        # [instrument (level = "trace" , skip (tcx) , ret)] fn variance_of_opaque (tcx : TyCtxt < '_ > , item_def_id : LocalDefId , force_capture_trait_args : ForceCaptureTraitArgs ,) -> & [ty :: Variance] { let generics = tcx . generics_of (item_def_id) ; struct OpaqueTypeLifetimeCollector < 'tcx > { tcx : TyCtxt < 'tcx > , root_def_id : DefId , variances : Vec < ty :: Variance > , } impl < 'tcx > OpaqueTypeLifetimeCollector < 'tcx > { # [instrument (level = "trace" , skip (self) , ret)] fn visit_opaque (& mut self , def_id : DefId , args : GenericArgsRef < 'tcx >) { if def_id != self . root_def_id && self . tcx . is_descendant_of (def_id , self . root_def_id) { let child_variances = self . tcx . variances_of (def_id) ; for (a , v) in args . iter () . zip_eq (child_variances) { if * v != ty :: Bivariant { a . visit_with (self) ; } } } else { args . visit_with (self) } } } impl < 'tcx > ty :: TypeVisitor < TyCtxt < 'tcx > > for OpaqueTypeLifetimeCollector < 'tcx > { # [instrument (level = "trace" , skip (self) , ret)] fn visit_region (& mut self , r : ty :: Region < 'tcx >) { if let ty :: RegionKind :: ReEarlyParam (ebr) = r . kind () { self . variances [ebr . index as usize] = ty :: Invariant ; } } # [instrument (level = "trace" , skip (self) , ret)] fn visit_ty (& mut self , t : Ty < 'tcx >) { match t . kind () { ty :: Alias (ty :: Opaque , ty :: AliasTy { def_id , args , .. }) => { self . visit_opaque (* def_id , args) ; } _ => t . super_visit_with (self) , } } } let mut variances = vec ! [ty :: Invariant ; generics . count ()] ; { let mut generics = generics ; while let Some (def_id) = generics . parent { generics = tcx . generics_of (def_id) ; if matches ! (force_capture_trait_args , ForceCaptureTraitArgs :: Yes) && generics . parent . is_none () { debug_assert_eq ! (tcx . def_kind (def_id) , DefKind :: Trait) ; break ; } for param in & generics . own_params { match param . kind { ty :: GenericParamDefKind :: Lifetime => { variances [param . index as usize] = ty :: Bivariant ; } ty :: GenericParamDefKind :: Type { .. } | ty :: GenericParamDefKind :: Const { .. } => { } } } } } let mut collector = OpaqueTypeLifetimeCollector { tcx , root_def_id : item_def_id . to_def_id () , variances } ; let id_args = ty :: GenericArgs :: identity_for_item (tcx , item_def_id) ; for (pred , _) in tcx . explicit_item_bounds (item_def_id) . iter_instantiated_copied (tcx , id_args) { debug ! (? pred) ; match pred . kind () . skip_binder () { ty :: ClauseKind :: Trait (ty :: TraitPredicate { trait_ref : ty :: TraitRef { def_id : _ , args , .. } , polarity : _ , }) | ty :: ClauseKind :: HostEffect (ty :: HostEffectPredicate { trait_ref : ty :: TraitRef { def_id : _ , args , .. } , constness : _ , }) => { for arg in & args [1 ..] { arg . visit_with (& mut collector) ; } } ty :: ClauseKind :: Projection (ty :: ProjectionPredicate { projection_term : ty :: AliasTerm { args , .. } , term , }) => { for arg in & args [1 ..] { arg . visit_with (& mut collector) ; } term . visit_with (& mut collector) ; } ty :: ClauseKind :: TypeOutlives (ty :: OutlivesPredicate (_ , region)) => { region . visit_with (& mut collector) ; } _ => { pred . visit_with (& mut collector) ; } } } tcx . arena . alloc_from_iter (collector . variances) }
    };
}

variance_of_opaque!();